/** The recorded scan's address: its run id (its number, #1, is a display ordinal). */
const RUN: string = RECORDED.scan.scan.id;
const AT = '#/sentinel/' + RUN;

/**
 * The recorded answers as a Copilot review that used every turn reads (the demo's: two turns allowed, both used, no
 * answer): each review stage and its unit name their runner, their turn limit, the files the model asked for and the
 * record's own `unfinished`, the fields the read model now carries (owner-ui-read-model.test.ts folds them for real).
 */
function unfinishedReviews(recorded: Json): Json {
  const r: Json = structuredClone(recorded);
  const runner = { id: 'copilot-cli', mode: 'brokered', local: false };
  const counted = (n: number, of: number, unit: string, bizUnit: string, scope: string) => ({
    n,
    of,
    unit,
    bizUnit,
    scope,
    source: 'sentinel viewer read model draft-1 · review records',
  });
  const patch = (c: Json, scope: string) => {
    c.turns = counted(
      c.turns.n,
      c.turns.n,
      'sentinel.viewer.count.turnsOf',
      'sentinel.viewer.count.exchangesOf',
      scope,
    );
    c.inspected = counted(1, c.inputs.n, 'sentinel.viewer.count.inspected', 'sentinel.viewer.count.inspected', scope);
  };
  // an unfinished review gave no answer, so it left no observation
  const none = (c: Json) => {
    if (c?.modelObservations) c.modelObservations = { ...c.modelObservations, n: 0 };
  };
  const stageOf = (st: Json) => {
    if (st.kind !== 'agent') return;
    st.provenance.runner = runner;
    patch(st.counts, 'sentinel.viewer.scope.stage');
    none(st.counts);
    st.produces = st.produces.filter((io: Json) => io.key !== 'sentinel.viewer.io.observations');
    st.review = {
      outcome: 'unfinished',
      unfinished: counted(
        st.counts.units.n,
        st.counts.units.n,
        'sentinel.viewer.count.unfinished',
        'sentinel.viewer.count.unfinished',
        'sentinel.viewer.scope.stage',
      ),
    };
  };
  r.scan.stages.forEach(stageOf);
  for (const answer of Object.values(r.stages) as Json[]) {
    stageOf(answer.stage);
    for (const u of answer.units)
      if (u.review) {
        u.review.runner = runner;
        u.review.outcome = 'unfinished';
        u.review.verdict = null;
        u.review.observations = [];
        patch(u.counts, 'sentinel.viewer.scope.review');
        none(u.counts);
      }
  }
  for (const row of [r.scan.scan, ...r.scans.scans, ...Object.values(r.stages).map((a: Json) => a.scan)])
    none(row.counts);
  for (const opened of Object.values(r.units) as Json[])
    for (const answer of Object.values(opened) as Json[])
      if (answer.unit?.review) {
        answer.unit.review.runner = runner;
        answer.unit.review.outcome = 'unfinished';
        answer.unit.review.verdict = null;
        answer.unit.review.observations = [];
        patch(answer.unit.counts, 'sentinel.viewer.scope.review');
        none(answer.unit.counts);
      }
  return r;
}

async function standIn(
  page: Page,
  baseURL: string | undefined,
  opts: {
    scanAction?: Json;
    readOnly?: boolean;
    holdScans?: Promise<void>;
    scanState?: string;
    unfinished?: boolean;
    companion?: Json;
  } = {},
) {
  const REC: Json = opts.unfinished ? unfinishedReviews(RECORDED) : RECORDED;
  // the viewer's own origin: the stand-in answers only it, as the companion does
  const origin = new URL(baseURL ?? 'http://localhost').origin;
  const version: Json = await (await page.request.get('/api/version')).json();
  const instance = version.session.instance;
  const scans = { ...REC.scans, ...(opts.scanAction ? { scanAction: opts.scanAction } : {}) };
  // The page Farsight serves names the companion it may frame; the server would, with a live descriptor.
  await page.route(
    (url) => url.pathname === '/' || url.pathname === '/index.html',
    async (route) => {
      const response = await route.fetch();
      const body = (await response.text()).replace(
        'data-sentinel-owner-origin=""',
        `data-sentinel-owner-origin="${STUB}"`,
      );
      const csp = response.headers()['content-security-policy'] ?? '';
      await route.fulfill({
        response,
        body,
        headers: { ...response.headers(), 'content-security-policy': `${csp} ${STUB}` },
      });
    },
  );
  if (opts.readOnly)
    await page.route('**/api/version', async (route) => {
      const response = await route.fetch();
      const v = await response.json();
      await route.fulfill({ response, json: { ...v, session: { ...v.session, readOnly: true, why: 'flag' } } });
    });
  await page.route('**/api/sentinel/companion', (route) =>
    route.fulfill({
      json: opts.companion ?? { available: true, ownerOrigin: STUB },
      headers: { 'cache-control': 'no-store' },
    }),
  );
  // The paired owner frame: asks its parent for the context, then hands it a read pass; a Scan press is noted.
  await page.route(`${STUB}/frame`, (route) =>
    route.fulfill({
      contentType: 'text/html; charset=utf-8',
      body: `<!doctype html><meta charset="utf-8"><body><p id="said">paired</p><script>
        const parentOrigin = ${JSON.stringify(origin)};
        const frameNonce = 'frame-' + '1'.repeat(32), documentId = 'document-' + '2'.repeat(32), id = '3'.repeat(64);
        addEventListener('message', (e) => {
          if (e.origin !== parentOrigin || !e.data) return;
          if (e.data.type === 'sentinel-owner-context' && e.data.id === id)
            parent.postMessage({ type: 'sentinel-owner-read', frameNonce, documentId, hostInstance: ${JSON.stringify(instance)},
              pass: ${JSON.stringify(PASS)}, expiresAt: new Date(Date.now() + 3600000).toISOString() }, parentOrigin);
          if (e.data.type === 'sentinel-owner-control' && e.data.frameNonce === frameNonce)
            document.getElementById('said').textContent = 'control ' + e.data.action + ' ' + e.data.runId;
          if (e.data.type === 'sentinel-owner-scan' && e.data.frameNonce === frameNonce)
            document.getElementById('said').textContent = 'scan requested';
        });
        parent.postMessage({ type: 'sentinel-owner-context-request', id, frameNonce, documentId,
          hostInstance: ${JSON.stringify(instance)} }, parentOrigin);
      </script></body>`,
    }),
  );
  await page.route(`${STUB}/api/sentinel/**`, async (route: Route) => {
    const req = route.request();
    const cors = { 'access-control-allow-origin': origin, vary: 'Origin' };
    if (req.method() === 'OPTIONS')
      return route.fulfill({
        status: 204,
        headers: { ...cors, 'access-control-allow-methods': 'GET', 'access-control-allow-headers': 'authorization' },
      });
    if (req.headers()['authorization'] !== `Bearer ${PASS}`)
      return route.fulfill({ status: 401, headers: cors, json: { error: 'sentinel.viewer.notPaired' } });
    const path = new URL(req.url()).pathname.replace('/api/sentinel/', '');
    if (path === 'scans' && opts.holdScans) await opts.holdScans; // the list answers late
    // a finished scan's report, as the companion delivers it: whole, named, for download
    // the workspace's pipeline, for the edit mode one press away: this stand-in workspace has none
    if (path === 'pipeline')
      return route.fulfill({
        headers: cors,
        json: {
          schema: 'sentinel-viewer-pipeline/draft-1',
          trust: 'missing',
          reasonCode: null,
          pipeline: null,
          fileDigest: null,
          digest: null,
          problems: [],
          readOnly: true,
        },
      });
    const report = /^scans\/([^/]+)\/report\/(html|md)$/.exec(path);
    if (report && decodeURIComponent(report[1]!) === RUN)
      return route.fulfill({
        headers: {
          ...cors,
          'access-control-expose-headers': 'x-sentinel-format-digest, content-disposition',
          'content-type': report[2] === 'html' ? 'text/html; charset=utf-8' : 'text/markdown; charset=utf-8',
          'content-disposition': `attachment; filename="sentinel-scan-1.${report[2]}"`,
        },
        body: report[2] === 'html' ? '<!doctype html><title>Sentinel report</title>' : '# Sentinel report\n',
      });
    const m = /^scans(?:\/before\/(\d+)|\/([^/]+)(?:\/stages\/([^/]+)(?:\/units\/(\d+))?)?)?$/.exec(path);
    const run = m?.[2] ? decodeURIComponent(m[2]) : null;
    const stage = m?.[3] ? decodeURIComponent(m[3]) : null;
    const answer = !m
      ? null
      : m[1]
        ? {
            ...scans,
            scans: [],
            counts: { ...scans.counts, shown: { ...scans.counts.shown, n: 0 } },
            page: { before: Number(m[1]), older: null },
            more: false,
          }
        : !run
          ? scans
          : run !== RUN
            ? null
            : !stage
              ? opts.scanState
                ? { ...REC.scan, scan: { ...REC.scan.scan, state: opts.scanState } }
                : REC.scan
              : !m[4]
                ? REC.stages[stage]
                : REC.units[stage]?.[m[4]];
    return answer
      ? route.fulfill({ headers: cors, json: answer })
      : route.fulfill({ status: 404, headers: cors, json: { error: 'sentinel.viewer.scanUnknown' } });
  });
}

/** The words a reader can see under `root`, as written. */
async function visibleWords(page: Page, root: string): Promise<string> {
  return page.evaluate((sel) => {
    const out: string[] = [];
    for (const r of Array.from(document.querySelectorAll(sel))) {
      const w = document.createTreeWalker(r, NodeFilter.SHOW_TEXT);
      let n: Node | null;
      while ((n = w.nextNode())) {
        const el = n.parentElement;
        if (!el || !n.textContent?.trim()) continue;
        if (el.closest('[hidden],details:not([open]) > :not(summary),iframe')) continue;
        const box = el.getBoundingClientRect();
        if (!box.width || !box.height) continue;
        out.push(n.textContent.trim());
      }
    }
    return out.join('\n');
  }, root);
}

